import{_ as a,o as t,c as i,ag as n}from"./chunks/framework.BGkQCay2.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Vex","text":"Systems programming with parallelism in the language","tagline":"Explicit ownership, practical concurrency, and a path to accelerated code.","actions":[{"theme":"brand","text":"Get Started","link":"/guide/introduction"},{"theme":"alt","text":"Install Vex","link":"/guide/installation"},{"theme":"alt","text":"Check language status","link":"/guide/language-status"}]},"features":[{"title":"A systems language with a small core","details":"Functions, immutable bindings, explicit mutation, structs, enums, pattern matching, and typed low-level access share one consistent model."},{"title":"Memory-Safe Systems Model","details":"Ownership, borrowing, non-lexical lifetime analysis, and explicit unsafe boundaries are part of the language rather than library conventions."},{"title":"Concurrency as a language feature","details":"go blocks, async functions, await, and channels are designed to work with the same type and ownership checks as synchronous code."},{"title":"Data-parallel foundations","details":"Arrays, tensor-oriented operations, reductions, and the Silicon IR pipeline provide an experimental path to SIMD and accelerator backends."},{"title":"Direct systems interop","details":"Typed pointers, spans, raw buffers, FFI declarations, and freestanding builds cover the cases where a runtime abstraction is not enough."},{"title":"A toolchain that explains itself","details":"The compiler, checker, formatter, test runner, documentation generator, LSP, and package tools are documented separately and honestly."},{"title":"Typed compile-time programming","details":"Strict CTFE, typed reflection, partial evaluation, and structural declaration generation reuse ordinary Vex semantics without token macros or a second runtime model."}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),r={name:"index.md"};function o(s,e,l,d,c,h){return t(),i("div",null,[...e[0]||(e[0]=[n('<h2 id="start-with-the-language" tabindex="-1">Start with the language <a class="header-anchor" href="#start-with-the-language" aria-label="Permalink to &quot;Start with the language&quot;">​</a></h2><p>The guide is organized as a progression rather than a catalogue of isolated features:</p><ol><li>Read the <a href="/docs/guide/introduction">introduction</a> to understand Vex&#39;s design and the current implementation boundary.</li><li>Follow <a href="/docs/guide/installation">installation</a> to build the compiler and run a first program.</li><li>Learn the core language through <a href="/docs/guide/basics/syntax">syntax</a>, <a href="/docs/guide/basics/variables">variables</a>, <a href="/docs/guide/basics/functions">functions</a>, and <a href="/docs/guide/basics/control-flow">control flow</a>.</li><li>Continue with <a href="/docs/guide/types/primitives">types</a>, <a href="/docs/guide/types/enums">enums</a>, <a href="/docs/guide/memory/ownership">ownership</a>, and <a href="/docs/guide/error-handling">error handling</a>.</li><li>Use the specialist sections for <a href="/docs/guide/concurrency/overview">concurrency</a>, <a href="/docs/guide/simd/">SIMD and tensors</a>, <a href="/docs/guide/gpu/">GPU and SIR</a>, <a href="/docs/guide/ffi">FFI</a>, and <a href="/docs/guide/tooling/full-toolchain">tooling</a>.</li><li>Continue with <a href="/docs/guide/advanced/comptime">compile-time evaluation</a> and <a href="/docs/guide/advanced/comptime-declarations">structural declaration generation</a> when you need typed metaprogramming.</li></ol><p>Every language example is intended to be small enough to copy into a file. When a feature is not ready for general use, the page labels that fact and points to the relevant limitation instead of presenting a design sketch as production behavior.</p><h2 id="find-the-right-reference" tabindex="-1">Find the right reference <a class="header-anchor" href="#find-the-right-reference" aria-label="Permalink to &quot;Find the right reference&quot;">​</a></h2><ul><li><a href="/docs/guide/language-status">Language status</a> explains what is verified, experimental, or still planned.</li><li><a href="/docs/architecture/">Architecture</a> describes the compiler pipeline, runtime, and intermediate representations.</li><li><a href="/docs/references/">Reference</a> documents command behavior for the CLI, test runner, documentation generator, and package tools.</li><li><a href="/docs/std/">Standard library</a> is the API reference generated from the library source.</li></ul>',6)])])}const p=a(r,[["render",o]]);export{g as __pageData,p as default};
